function normalize(raw){if(!raw||typeof raw!=='object')throw Error('Estrutura de backup inválida');const d=raw.db||raw;if(!Array.isArray(d.products)||!Array.isArray(d.sales))throw Error('O arquivo não contém produtos e vendas do Ely/KLSistemas');const out={app:'KLSistemas',version:2,db:{products:[],sales:[],customers:[],suppliers:[],invoices:[],debts:[],receipts:[],bills:[],exits:[],audit:[],saleSeq:0,...clone(d)},settings:{...clone(defaults),...(raw.settings||{})}};for(const k of ['products','sales','customers','suppliers','invoices','debts','receipts','bills','exits','audit'])if(!Array.isArray(out.db[k]))out.db[k]=[];out.db.products=out.db.products.map(p=>({...p,active:p.active!==false,category:p.category||'Geral',unit:p.unit||'UN',shortcut:p.shortcut||''}));out.db.customers=out.db.customers.map(c=>({...c,active:c.active!==false,limit:Number(c.limit)||0}));out.db.sales=out.db.sales.map(s=>({...s,items:(s.items||[{product:s.product,qty:s.qty,price:s.price,cost:s.cost}]).map(i=>({...i,name:i.name||out.db.products.find(p=>p.id===i.product)?.name||'Produto removido'})),status:s.status||'completed'}));out.db.saleSeq=Math.max(Number(d.saleSeq)||0,...out.db.sales.map(s=>Number(s.id)||0));if(d.nfs?.length&&!out.db.invoices.length)out.db.invoices=d.nfs.map(n=>({...n,legacy:true,items:[{product:n.product,qty:n.qty,cost:n.cost}],due:localDay(n.date),paymentStatus:'unreconciled'}));out.settings.menu=modules.map(([id,label])=>out.settings.menu?.find(x=>x.id===id)||{id,label,visible:true}).sort((a,b)=>(raw.settings?.menu?.findIndex(x=>x.id===a.id)??-1)-(raw.settings?.menu?.findIndex(x=>x.id===b.id)??-1));if(!raw.settings?.printingVersion){out.settings.autoPrint=true;out.settings.printingVersion=1}return out}
