async function api(path,body,raw=false){const r=await fetch('/mercado'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':raw?'application/octet-stream':'application/json'},body:body===undefined?undefined:raw?body:JSON.stringify(body)});const j=await r.json();if(!r.ok){if(r.status===401&&hosted)loginView();throw Error(j.error||'Falha de comunicação')};return j}
