function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`}
function kpi(label,value,note,ic='finance'){return `<div class="card"><span class="kpi-icon">${icon(ic)}</span><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty">Nenhum registro encontrado.</div></td></tr>`}</tbody></table></div>`}
function field(label,id,value='',type='text',attrs=''){return `<label>${label}<input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function select(label,id,options,value=''){return `<label>${label}<select id="${id}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function modal(title,sub,content){stopCamera();$('modalContent').innerHTML=`<button class="close" onclick="closeModal()">×</button><h2>${title}</h2><p class="subtitle">${sub}</p>${content}`;$('modal').showModal()}
