function render(){apply();if(hosted){const label=document.querySelector('.sidebar-bottom');if(label)label.innerHTML='<span class="dot"></span> Operação online <button class="ghost" onclick="logoutCloud()">Sair</button>';}const views={dashboard:dashboardView,pdv:pdvView,products:productsView,customers:customersView,fiado:fiadoView,suppliers:suppliersView,invoices:invoicesView,finance:financeView,sales:salesView,settings:settingsView,updates:updatesView};$('main').innerHTML=(views[page]||dashboardView)();if(page==='pdv'){if(!matchMedia('(pointer: coarse)').matches)$('scan').focus();renderCart()}if(page==='settings'){renderMenuEditor();loadPrinters()}}
