function dashboardView(){const s=activeSales().filter(s=>localDay(s.date)===today()),revenue=round(s.reduce((a,s)=>a+s.total,0)),open=db().debts.reduce((a,d)=>a+balance(d),0),low=db().products.filter(p=>p.active&&p.stock<=(p.minStock??3)),m=activeSales().filter(s=>localDay(s.date).startsWith(month())),last7=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('sv-SE');return{label:d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.',''),v:activeSales().filter(s=>localDay(s.date)===key).reduce((a,s)=>a+s.total,0)}}),max=Math.max(...last7.map(x=>x.v),1);return head('Seu negócio em perspectiva','Acompanhe os números e mantenha a operação em dia.',`<button onclick="location.hash='pdv'">+ Nova venda</button>`)+`<div class="grid kpis">${kpi('Vendas de hoje',money(revenue),`${s.length} vendas concluídas`,'pdv')}${kpi('Ticket médio',money(s.length?revenue/s.length:0),'Média das vendas de hoje','sales')}${kpi('Fiado a receber',money(open),'Saldo de todos os clientes','fiado')}${kpi('Alertas de estoque',low.length,'Produtos no nível mínimo','products')}</div><div class="grid two"><div class="card"><div class="card-head"><h3>Desempenho das vendas</h3><span class="badge neutral">Últimos 7 dias</span></div><div class="kpi-value">${money(last7.reduce((a,x)=>a+x.v,0))}</div><div class="chart">${last7.map(x=>`<div class="chart-col" title="${money(x.v)}"><div class="chart-bar" style="height:${Math.max(2,x.v/max*100)}%"></div><small>${x.label}</small></div>`).join('')}</div></div><div class="card"><div class="card-head"><h3>Resumo do mês</h3><span class="badge">${month().split('-').reverse().join('/')}</span></div>${line('Faturamento',money(m.reduce((a,s)=>a+s.total,0)))}${line('Vendas realizadas',m.length)}${line('Clientes cadastrados',db().customers.filter(c=>c.active).length)}${line('Contas a pagar',money(db().bills.filter(b=>b.type==='payable'&&!b.cancelled).reduce((a,b)=>a+b.value-billPaid(b),0)))}<button class="secondary full" style="margin-top:20px" onclick="location.hash='finance'">Abrir financeiro →</button></div></div><div class="grid two" style="margin-top:22px"><div class="card"><div class="card-head"><h3>Últimas vendas</h3><a class="ghost" href="#sales">Ver todas →</a></div>${salesTable(db().sales.slice(-5).reverse())}</div><div class="card"><div class="card-head"><h3>Reposição de estoque</h3><span class="badge warn">${low.length} itens</span></div>${low.slice(0,6).map(p=>line(esc(p.name),`<span class="badge ${p.stock<=0?'red':'warn'}">${p.stock} ${esc(p.unit)}</span>`)).join('')||'<div class="empty">Estoque em dia.</div>'}</div></div>`}
function line(a,b,strong=false){return `<div class="summary-line ${strong?'strong':''}"><span>${a}</span><span>${b}</span></div>`}
function pdvView(){return head('Frente de caixa','Uma venda rápida. Uma experiência melhor.',`<button class="secondary" onclick="newSale()">Limpar venda</button>`)+`<div id="printFeedback" hidden class="notice"></div><div class="pdv"><div><div class="scan"><input id="scan" placeholder="Código, nome ou atalho: MU, PP, 3xPP, 0,250xMU" autocomplete="off" onkeydown="if(event.key==='Enter'){event.preventDefault();scan()}" oninput="scanInput()"></div><div id="scanResults" class="scan-results" aria-live="polite"></div><div class="mobile-pdv-actions"><button type="button" class="secondary" onclick="openCamera()">📷 Ler com câmera</button><button type="button" class="secondary" onclick="openVA()">+ Valor avulso</button><button type="button" class="secondary" onclick="$('catalogQuery').focus();$('catalogQuery').scrollIntoView({block:'center',behavior:'smooth'})">Buscar produto</button></div><div class="scan-hint"><span><kbd>F2</kbd> Leitor &nbsp; <kbd>F4</kbd> Valor avulso &nbsp; <kbd>F9</kbd> Finalizar</span><span>Atalho abre peso/quantidade • Enter também confirma</span></div><div class="card-head"><h3>Catálogo de produtos</h3><input class="search" style="max-width:200px" id="catalogQuery" placeholder="Nome, código ou categoria…" aria-label="Buscar produto para vender" type="search" autocomplete="off" oninput="renderCatalog()"></div><div id="catalog" class="product-grid">${catalogCards('')}</div></div><div class="card checkout"><div class="checkout-title"><h3>Sacola</h3><span id="cartCount" class="badge neutral">0 itens</span></div><div id="cartItems" class="cart-items"></div><div class="checkout-bottom"><label>Cliente<select id="saleCustomer" onchange="saleCustomer=this.value">${customerOptions(saleCustomer)}</select></label><div class="payment-options">${['Dinheiro','Pix','Cartão','Fiado'].map(p=>`<button class="${payment===p?'selected':''}" onclick="setPayment('${p}')">${p}</button>`).join('')}</div><div id="paymentDetails"></div><div class="total"><span>Total da venda</span><strong id="cartTotal">${money(0)}</strong></div><button class="full" onclick="finalizeSale()">Finalizar venda <span style="opacity:.6;margin-left:10px">F9</span></button><div class="muted" style="font-size:10px;text-align:center;margin-top:12px">${cfg().autoPrint?'Impressão do comprovante ativada':'Comprovante disponível após a venda'}</div></div></div></div>`}
function customerOptions(value,all=false){return `<option value="">${all?'Selecione o cliente':'Consumidor não identificado'}</option>`+db().customers.filter(c=>c.active).map(c=>`<option value="${c.id}" ${String(c.id)===String(value)?'selected':''}>${esc(c.name)}</option>`).join('')}


function productCategories(){return [...new Set(['GERAL','FRIOS','PADARIA','BEBIDAS','MERCEARIA','HORTIFRUTI','LIMPEZA',...db().products.map(p=>(p.category||'GERAL').toLocaleUpperCase('pt-BR'))])].sort((a,b)=>a.localeCompare(b,'pt-BR'))}
function productUnitChanged(){const weighted=$('pUnit').value==='KG';for(const id of ['pStock','pMin'])$(id).step=weighted?'0.001':'1';$('pPrice').parentElement.firstChild.textContent=weighted?'Preço de 1 kg (R$)':'Preço por unidade de venda (R$)';$('pCost').parentElement.firstChild.textContent=weighted?'Custo de 1 kg (R$)':'Custo por unidade de venda (R$)';$('productUnitHelp').textContent=weighted?'Venda por peso: informe preço/custo por 1 kg e o estoque em kg. Ex.: 0,250 = 250 g.':'Venda por quantidade: cada unidade cadastrada é uma peça. Informe preço e estoque por unidade.'}
function productCategoryChanged(){const other=$('pCategory').value==='__OUTRA__';$('pCategoryCustomWrap').hidden=!other;if(other)$('pCategoryCustom').focus()}
function acceptCameraCode(code,qty=null){const products=db().products.filter(p=>p.active&&String(p.barcode)===String(code));if($('scan'))$('scan').value=(qty===null?'':qty+'x')+code;if(products.length!==1){renderScanResults();toast(products.length?'Código duplicado no catálogo. Confira o cadastro.':'Código não cadastrado. Cadastre o produto antes de vender.');return}const p=products[0];if(p.unit==='KG'&&qty===null)chooseProduct(p.id);else if(addCart(p.id,qty===null?1:qty)){clearScan();toast(p.name+' adicionado à sacola.')}}

function quantityRound(n){return Math.round(n*1000)/1000}
function validQty(p,q,zero=false){return !!p&&Number.isFinite(q)&&q>=(zero?0:p.unit==='KG'?0.001:1)&&q<=100000000&&(p.unit==='KG'?Math.abs(q*1000-Math.round(q*1000))<1e-6:Number.isInteger(q))}
function parseScan(text){text=text.trim();if(!text||text.includes('*'))return null;const m=text.match(/^(\d+(?:[.,]\d{1,3})?)\s*[xX×]\s*(.*)$/);return m?{key:m[2].trim(),qty:Number(m[1].replace(',','.'))}:{key:text,qty:null}}
function findProducts(key){const k=searchKey(key.trim());if(!k)return [];const products=db().products.filter(p=>p.active);for(const get of [p=>p.barcode,p=>p.shortcut,p=>p.name]){const exact=products.filter(p=>get(p)&&searchKey(get(p))===k);if(exact.length)return exact}return products.filter(p=>searchKey(p.name).includes(k)||searchKey(p.shortcut).startsWith(k))}
function clearScan(){if($('scan')){$('scan').value='';$('scan').focus()}if($('scanResults'))$('scanResults').innerHTML=''}
function renderScanResults(){if(!$('scanResults'))return;const parsed=parseScan($('scan').value.trim());const found=parsed?findProducts(parsed.key):[];$('scanResults').innerHTML=found.slice(0,12).map(p=>`<button type="button" class="secondary" onclick="chooseProduct(${p.id},${parsed.qty===null?'null':parsed.qty})"><b>${esc(p.name)}</b><span>${esc(p.shortcut||'')} · ${money(p.price)} / ${esc(p.unit)}</span></button>`).join('')+(found.length>12?'<small>Refine a busca para ver os outros produtos.</small>':'')}
function chooseProduct(id,qty=null){clearTimeout(window.scanTimer);if(qty!==null){if(addCart(id,qty))clearScan();return}const p=db().products.find(p=>p.id===id&&p.active);if(!p)return;modal((p.unit==='KG'?'Peso de ':'Quantidade de ')+esc(p.name),`${money(p.price)} por ${esc(p.unit)} • Estoque: ${p.stock} ${esc(p.unit)}`,`<form onsubmit="event.preventDefault();confirmProduct(${id})"><div class="grid equal">${field(p.unit==='KG'?'Peso':'Quantidade','itemQty',p.unit==='KG'?'':1,'text','required inputmode="decimal" autocomplete="off" oninput="previewItem('+id+')"')}${p.unit==='KG'?select('Informar peso em','weightUnit',[['KG','Quilogramas (kg)'],['G','Gramas (g)']],'KG'):''}</div><p id="itemPreview" class="notice"></p>${formEnd('Adicionar à sacola')}`);if($('weightUnit'))$('weightUnit').onchange=()=>previewItem(id);previewItem(id);$('itemQty').focus();$('itemQty').select()}
function itemQuantity(){const raw=$('itemQty').value.trim();if(!/^\d+(?:[.,]\d{1,3})?$/.test(raw))return NaN;const q=Number(raw.replace(',','.'));return $('weightUnit')?.value==='G'?q/1000:q}
function previewItem(id){const p=db().products.find(p=>p.id===id),q=itemQuantity();$('itemPreview').textContent=validQty(p,q)?`${q.toLocaleString('pt-BR',{maximumFractionDigits:3})} ${p.unit} × ${money(p.price)} = ${money(round(q*p.price))}`:'Informe uma quantidade válida. Peso mínimo: 1 g; precisão: 1 g.'}
function confirmProduct(id){if(addCart(id,itemQuantity())){closeModal();clearScan()}}

function searchKey(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function catalogCards(q){const list=db().products.filter(p=>p.active&&(!q||searchKey([p.name,p.barcode,p.shortcut,p.category].join(' ')).includes(searchKey(q)))).slice(0,60);return list.map(p=>`<button class="product" onclick="chooseProduct(${p.id})"><div class="product-symbol">${icon('products')}</div><b>${esc(p.name)}</b><strong>${money(p.price)} / ${esc(p.unit)}</strong><small>${p.stock} ${esc(p.unit)}</small></button>`).join('')||'<div class="empty">Cadastre produtos para começar.</div>'}
function renderCatalog(){$('catalog').innerHTML=catalogCards($('catalogQuery').value)}
function scanInput(){clearTimeout(window.scanTimer);const v=$('scan').value.trim(),parsed=parseScan(v);renderScanResults();if(!parsed?.key)return;const exactShortcut=db().products.filter(p=>p.active&&p.shortcut&&searchKey(p.shortcut)===searchKey(parsed.key));if(/^\d{8,14}$/.test(parsed.key)||exactShortcut.length===1)window.scanTimer=setTimeout(()=>{if($('scan')?.value.trim()===v&&!$('modal').open&&!$('cameraModal')?.open)scan()},450)}
function scan(){clearTimeout(window.scanTimer);const text=$('scan').value.trim();if(!text)return;if(/^VA$/i.test(text)){openVA();$('scan').value='';renderScanResults();return}const parsed=parseScan(text);if(!parsed)return toast('Use nome, atalho ou quantidadexproduto. Exemplo: 3xPP ou 0,250xMU.');if(!parsed.key)return toast('Agora digite ou leia o código do produto após o x.');const list=findProducts(parsed.key);if(list.length!==1){renderScanResults();return toast(list.length?'Selecione o produto na lista.':'Produto não encontrado. Confira o código ou o cadastro.')}const p=list[0];if(parsed.qty!==null){if(addCart(p.id,parsed.qty))clearScan()}else if(p.unit==='KG'||searchKey(p.shortcut)===searchKey(parsed.key)||searchKey(p.barcode)!==searchKey(parsed.key)){chooseProduct(p.id)}else if(addCart(p.id,1))clearScan()}
function addCart(id,qty=1){const p=db().products.find(p=>p.id===id&&p.active);if(!p||!validQty(p,qty)){toast('Quantidade inválida: use inteiros ou até 3 casas decimais para KG.');return false}const item=cart.find(i=>i.product===id),total=quantityRound((item?.qty||0)+qty);if(total>p.stock){toast('Estoque insuficiente: '+p.stock+' '+p.unit+' disponíveis.');return false}if(item)item.qty=total;else cart.push({product:p.id,name:p.name,qty:quantityRound(qty),price:round(p.price),cost:round(p.cost),unit:p.unit});renderCart();return true}
function openVA(){modal('Valor avulso','Lançamento sem movimentação de estoque. Informe o custo se houver.',`<form onsubmit="event.preventDefault();addVA()"><div class="grid equal">${field('Descrição','vaName','Valor avulso','text','required maxlength="120"')}${field('Valor unitário (R$)','vaValue','','text','required inputmode="decimal"')}${field('Quantidade','vaQty',1,'number','required min="1" step="1"')}${field('Custo unitário (R$)','vaCost','0','text','inputmode="decimal"')}</div>${formEnd('Adicionar à venda')}`);$('vaValue').focus()}
function addVA(){const v=amount($('vaValue').value),q=Number($('vaQty').value),cost=amount($('vaCost').value);if(!Number.isFinite(v)||v<=0||v>10000000||!Number.isInteger(q)||q<1||!Number.isFinite(cost)||cost<0)return toast('Informe valores válidos.');cart.push({product:null,name:$('vaName').value.trim()||'Valor avulso',qty:q,price:round(v),cost:round(cost),unit:'UN',avulso:true});closeModal();renderCart();$('scan').focus()}
function cartTotal(){return round(cart.reduce((a,i)=>a+round(i.qty*i.price),0))}
function renderCart(){if(!$('cartItems'))return;$('cartItems').innerHTML=cart.map((i,n)=>`<div class="cart-item"><div><b>${esc(i.name)}</b><small>${money(i.price)} / ${esc(i.unit||'UN')}${i.avulso?' • Avulso':''}</small></div><input aria-label="Quantidade ${esc(i.name)}" type="number" inputmode="decimal" min="${i.unit==='KG'?'0.001':'1'}" step="${i.unit==='KG'?'0.001':'1'}" value="${i.qty}" onchange="cartQty(${n},this.value)"><b>${money(i.qty*i.price)}</b><button title="Remover" onclick="cart.splice(${n},1);renderCart()">×</button></div>`).join('')||'<div class="empty">Seu carrinho está vazio.<br><small>Bipe um produto ou selecione no catálogo.</small></div>';$('cartTotal').textContent=money(cartTotal());$('cartCount').textContent=cart.length+' produtos';$('paymentDetails').innerHTML=payment==='Fiado'?field('Vencimento do fiado','saleDue',saleDue,'date','onchange="saleDue=this.value"'):payment==='Dinheiro'?`${field('Valor recebido (R$)','cashReceived','','text','inputmode="decimal" oninput="cashChange()"')}<div id="change" class="muted" style="margin-top:6px;font-size:11px">Informe para calcular o troco.</div>`:''}
function cartQty(n,v){const q=Number(String(v).replace(',','.')),i=cart[n],p=db().products.find(p=>p.id===i.product);if(!validQty(i,q)||(p&&q>p.stock))toast('Quantidade inválida ou estoque insuficiente.');else i.qty=quantityRound(q);renderCart()}
function cashChange(){const v=amount($('cashReceived').value);$('change').textContent=Number.isFinite(v)&&v>=cartTotal()?'Troco: '+money(v-cartTotal()):'Valor insuficiente para a venda.'}
function setPayment(p){payment=p;const selected=$('saleCustomer').value;saleCustomer=selected;render()}
function newSale(){if(cart.length&&!confirm('Descartar os itens da venda atual?'))return;cart=[];saleCustomer='';payment='Dinheiro';render()}
async function finalizeSale(){if(!cart.length)return toast('Adicione itens à venda.');if(saving)return;const c=db().customers.find(c=>String(c.id)===String(saleCustomer)&&c.active),total=cartTotal();if(payment==='Fiado'&&(!c||!saleDue))return toast('Selecione um cliente e o vencimento do fiado.');if(payment==='Fiado'&&c.limit>0&&customerBalance(c.id)+total>c.limit)return toast('O limite de crédito do cliente seria ultrapassado.');let cash=null;if(payment==='Dinheiro'&&$('cashReceived')?.value){cash=amount($('cashReceived').value);if(!Number.isFinite(cash)||cash<total)return toast('Valor recebido insuficiente.')}const n=clone(state);for(const i of cart){if(i.product!==null){const p=n.db.products.find(p=>p.id===i.product);if(!p||!p.active||!validQty(p,i.qty)||p.unit!==i.unit||p.stock<i.qty)return toast('Estoque alterado ou insuficiente. Revise a venda.');p.stock=quantityRound(p.stock-i.qty)}}const id=++n.db.saleSeq,s={id,date:now(),items:clone(cart),total,payment,status:'completed',customerId:c?.id||null,customerName:c?.name||'',cash,change:cash===null?0:round(cash-total)};n.db.sales.push(s);if(payment==='Fiado')n.db.debts.push({id:uid(),customerId:c.id,value:total,date:s.date,due:saleDue,description:'Venda #'+id,saleId:id});if(await save(n,'Venda #'+id+' • '+money(total))){cart=[];saleCustomer='';render();toast('Venda #'+id+' concluída.');if(cfg().autoPrint&&!hosted)await silentPrint(id)}}
function productsView(){const list=db().products.filter(p=>p.active&&[p.name,p.barcode,p.shortcut,p.category].join(' ').toLowerCase().includes(query.toLowerCase()));return head('Produtos e estoque','Catálogo, preços e reposição em um único lugar.',`<button onclick="productForm()">+ Novo produto</button>`)+`<div class="grid kpis">${kpi('Produtos ativos',db().products.filter(p=>p.active).length,'Itens no catálogo','products')}${kpi('Custo em estoque',money(db().products.filter(p=>p.active).reduce((a,p)=>a+p.cost*p.stock,0)),'Pelo custo atual')}${kpi('Potencial de venda',money(db().products.filter(p=>p.active).reduce((a,p)=>a+p.price*p.stock,0)),'Preço de venda × estoque')}${kpi('Estoque baixo',db().products.filter(p=>p.active&&p.stock<=(p.minStock??3)).length,'Revise a reposição','products')}</div><div class="card"><div class="toolbar"><input id="listQuery" class="search" value="${esc(query)}" placeholder="Nome, código ou categoria" oninput="filterList(this.value)"></div>${table(['Produto','Código','Categoria','Custo','Venda','Estoque','Ações'],list.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.barcode||'—')}<small>Atalho: ${esc(p.shortcut||'—')}</small></td><td>${esc(p.category)}</td><td>${money(p.cost)}</td><td><b>${money(p.price)}</b></td><td><span class="badge ${p.stock<=(p.minStock??3)?'warn':''}">${p.stock} ${esc(p.unit)}</span></td><td><button class="ghost small" onclick="productForm(${p.id})">Editar</button><button class="ghost small" onclick="stockForm(${p.id})">Ajustar</button><button class="ghost small" onclick="archiveProduct(${p.id})">Arquivar</button></td></tr>`))}</div>`}
function filterList(v){query=v;const start=$('listQuery').selectionStart;render();$('listQuery').focus();$('listQuery').setSelectionRange(start,start)}
function productForm(id){const p=db().products.find(p=>p.id===id)||{name:'',barcode:'',shortcut:'',category:'Geral',cost:0,price:0,stock:0,minStock:3,unit:'UN'};const categories=productCategories();const knownCategory=categories.find(c=>c.toLocaleUpperCase('pt-BR')===p.category.toLocaleUpperCase('pt-BR'));modal(id?'Editar produto':'Novo produto','Escolha a categoria e, separadamente, como o produto será vendido: por unidade ou por peso.',`<form onsubmit="event.preventDefault();saveProduct(${id||0})"><div class="grid equal">${field('Nome','pName',p.name,'text','required maxlength="160"')}<div>${field('Código de barras (opcional)','pBarcode',p.barcode,'text','maxlength="80"')}<button type="button" class="secondary small" style="margin-top:8px" onclick="openCamera('product')">📷 Escanear código do produto</button></div>${field('Atalho de busca (opcional)','pShortcut',p.shortcut||'','text','maxlength="20" placeholder="Escolha um atalho, ex.: MU ou PP"')}${select('Categoria do produto','pCategory',[...categories.map(c=>[c,c]),['__OUTRA__','Outra categoria…']],knownCategory||'__OUTRA__')}<div id="pCategoryCustomWrap" ${knownCategory?'hidden':''}>${field('Digite a categoria','pCategoryCustom',knownCategory?'':p.category,'text','maxlength="80" placeholder="Ex.: CONGELADOS"')}</div>${select('Como vender e controlar o estoque?','pUnit',[['UN','Por unidade ou quantidade (UN)'],['KG','Por peso, em quilogramas (KG)'],['CX','Por caixa (CX)'],['PCT','Por pacote (PCT)']],p.unit)}${field('Custo conforme a unidade escolhida (R$)','pCost',p.cost,'number','required min="0" step="0.01"')}${field('Preço conforme a unidade escolhida (R$)','pPrice',p.price,'number','required min="0.01" step="0.01"')}${field('Estoque inicial na unidade escolhida','pStock',p.stock,'number',`required min="0" step="0.001" ${id?'disabled':''}`)}${field('Estoque mínimo na unidade escolhida','pMin',p.minStock??3,'number','required min="0" step="0.001"')}</div><p id="productUnitHelp" class="notice"></p><p class="muted">Exemplo: FRIOS pode ser vendido por KG ou por unidade. PADARIA também. A categoria não define a unidade; escolha a unidade no campo acima.</p>${formEnd()}`);$('pUnit').onchange=productUnitChanged;$('pCategory').onchange=productCategoryChanged;productUnitChanged();productCategoryChanged()}
async function saveProduct(id){const p={id:id||uid(),name:$('pName').value.trim(),barcode:$('pBarcode').value.trim(),shortcut:$('pShortcut').value.trim().toUpperCase(),category:($('pCategory').value==='__OUTRA__'?$('pCategoryCustom').value:$('pCategory').value).trim().toLocaleUpperCase('pt-BR')||'GERAL',unit:$('pUnit').value,cost:round($('pCost').value),price:round($('pPrice').value),stock:Number($('pStock').value),minStock:Number($('pMin').value),active:true};if(p.category.length>80)return toast('Categoria deve ter até 80 caracteres.');if(!p.name||!['UN','KG','CX','PCT'].includes(p.unit)||!Number.isFinite(p.cost)||p.cost<0||!Number.isFinite(p.price)||p.price<=0||!validQty(p,p.stock,true)||!validQty(p,p.minStock,true))return toast('Confira preços e estoque. KG aceita até 3 casas decimais; as demais unidades exigem inteiros.');if(p.shortcut&&(!/^[A-Z0-9][A-Z0-9_-]{0,19}$/.test(p.shortcut)||p.shortcut==='VA'||/^\d+X/.test(p.shortcut)))return toast('Use até 20 letras/números no atalho. VA é reservado; atalhos não podem começar com número seguido de X.');const keys=[p.barcode,p.shortcut].filter(Boolean).map(searchKey);if(db().products.some(x=>x.id!==id&&[x.barcode,x.shortcut].filter(Boolean).some(k=>keys.includes(searchKey(k)))))return toast('Código ou atalho já cadastrado em outro produto.');const old=db().products.find(x=>x.id===id);if(old&&old.unit!==p.unit&&(old.stock!==0||cart.some(i=>i.product===id)||db().sales.some(s=>s.items.some(i=>i.product===id))||db().invoices.some(n=>n.items?.some(i=>i.product===id))||db().exits.some(e=>e.product===id)))return toast('Produto com estoque ou histórico não pode trocar de unidade. Cadastre outro produto para preservar os registros.');const n=clone(state);if(id)Object.assign(n.db.products.find(x=>x.id===id),p);else n.db.products.push(p);if(await save(n,'Produto: '+p.name)){closeModal();render();toast('Produto salvo.')}}
async function archiveProduct(id){const p=db().products.find(p=>p.id===id);if(p.stock>0)return toast('Zere ou transfira o estoque antes de arquivar.');if(!confirm('Arquivar '+p.name+'? O histórico será preservado.'))return;const n=clone(state);n.db.products.find(p=>p.id===id).active=false;if(await save(n,'Produto arquivado: '+p.name))render()}
function stockForm(id){const p=db().products.find(p=>p.id===id);modal('Ajuste de estoque',esc(p.name)+' • Saldo atual: '+p.stock,`<form onsubmit="event.preventDefault();stockSave(${id})"><div class="grid equal">${select('Operação','stockType',[['loss','Perda / avaria'],['in','Entrada de ajuste'],['count','Contagem física']])}${field('Quantidade em '+esc(p.unit),'stockQty','','number',`required min="0" step="${p.unit==='KG'?'0.001':'1'}"`)}${field('Motivo obrigatório','stockReason','','text','required minlength="3"')}</div>${formEnd('Registrar ajuste')}`)}
async function stockSave(id){const n=clone(state),p=n.db.products.find(p=>p.id===id),q=Number($('stockQty').value),type=$('stockType').value,reason=$('stockReason').value.trim();if(!validQty(p,q,true)||reason.length<3)return toast('Informe quantidade e motivo válidos.');const delta=type==='count'?q-p.stock:type==='in'?q:-q;if(p.stock+delta<0)return toast('Estoque insuficiente.');p.stock=quantityRound(p.stock+delta);if(delta<0)n.db.exits.push({id:uid(),date:now(),type:'loss',value:round(-delta*p.cost),product:id,qty:-delta,desc:reason});if(await save(n,`Ajuste ${p.name}: ${delta} • ${reason}`)){closeModal();render()}}
function customersView(){const list=db().customers.filter(c=>c.active&&[c.name,c.phone,c.document].join(' ').toLowerCase().includes(query.toLowerCase()));return head('Clientes','Relacionamento, histórico e crédito sob controle.',`<button onclick="customerForm()">+ Novo cliente</button>`)+`<div class="card"><div class="toolbar"><input id="listQuery" class="search" placeholder="Buscar nome, telefone ou documento" value="${esc(query)}" oninput="filterList(this.value)"></div>${table(['Cliente','Contato','Documento','Limite','Fiado aberto','Ações'],list.map(c=>`<tr><td><b>${esc(c.name)}</b><small>${esc(c.address||'')}</small></td><td>${esc(c.phone||'—')}<small>${esc(c.email||'')}</small></td><td>${esc(c.document||'—')}</td><td>${c.limit?money(c.limit):'Sem limite definido'}</td><td>${money(customerBalance(c.id))}</td><td><button class="ghost small" onclick="customerForm(${c.id})">Editar</button><button class="ghost small" onclick="customerStatement(${c.id})">Extrato</button></td></tr>`))}</div>`}
function customerForm(id){const c=db().customers.find(c=>c.id===id)||{};modal(id?'Editar cliente':'Cadastrar cliente','Cadastro compartilhado entre PDV, CRM e FIADO.',`<form onsubmit="event.preventDefault();saveCustomer(${id||0})"><div class="grid equal">${field('Nome completo','cName',c.name,'text','required maxlength="160"')}${field('CPF / CNPJ','cDoc',c.document)}${field('Telefone / WhatsApp','cPhone',c.phone)}${field('E-mail','cEmail',c.email,'email')}${field('Endereço','cAddress',c.address)}${field('Limite de fiado (0 = sem limite)','cLimit',c.limit||0,'number','min="0" step="0.01"')}</div><label style="margin-top:16px">Observações<textarea id="cNotes">${esc(c.notes||'')}</textarea></label>${formEnd()}`)}
async function saveCustomer(id){const n=clone(state),c={id:id||uid(),name:$('cName').value.trim(),document:$('cDoc').value.trim(),phone:$('cPhone').value.trim(),email:$('cEmail').value.trim(),address:$('cAddress').value.trim(),limit:round($('cLimit').value),notes:$('cNotes').value,active:true};if(!c.name||!Number.isFinite(c.limit)||c.limit<0)return toast('Nome ou limite inválido.');if(id)Object.assign(n.db.customers.find(x=>x.id===id),c);else n.db.customers.push(c);if(await save(n,'Cliente: '+c.name)){closeModal();render()}}
function fiadoView(){const debts=db().debts.filter(d=>!d.cancelled),total=debts.reduce((a,d)=>a+balance(d),0),overdue=debts.filter(d=>d.due<today()).reduce((a,d)=>a+balance(d),0),receipts=db().receipts.filter(r=>!r.cancelled&&localDay(r.date).startsWith(month())).reduce((a,r)=>a+r.value,0);return head('FIADO','Venda com controle. Receba com clareza.',`<button class="secondary" onclick="customerForm()">+ Cliente</button><button onclick="debtForm()">+ Lançar fiado</button>`)+`<div class="grid kpis">${kpi('Saldo a receber',money(total),'Fiados em aberto','fiado')}${kpi('Saldo vencido',money(overdue),'Vencimento anterior a hoje')}${kpi('Recebido no mês',money(receipts),'Pagamentos de fiado')}${kpi('Clientes com saldo',db().customers.filter(c=>customerBalance(c.id)>0).length,'Carteira de crédito','customers')}</div><div class="card"><div class="toolbar"><input id="listQuery" class="search" value="${esc(query)}" placeholder="Buscar cliente ou lançamento" oninput="filterList(this.value)"></div>${table(['Cliente / lançamento','Emissão','Vencimento','Original','Recebido','Saldo','Ações'],debts.filter(d=>(db().customers.find(c=>c.id===d.customerId)?.name+' '+d.description).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(balance(b)>0)-(balance(a)>0)||a.due.localeCompare(b.due)).map(d=>`<tr><td><b>${esc(db().customers.find(c=>c.id===d.customerId)?.name||'Cliente removido')}</b><small>${esc(d.description)}</small></td><td>${date(d.date)}</td><td><span class="badge ${balance(d)>0&&d.due<today()?'red':'neutral'}">${date(d.due)}</span></td><td>${money(d.value)}</td><td>${money(received(d))}</td><td><b>${money(balance(d))}</b></td><td>${balance(d)>0?`<button class="ghost small" onclick="receiptForm(${d.id})">Receber</button>`:'<span class="badge">Quitado</span>'}<button class="ghost small" onclick="customerStatement(${d.customerId})">Extrato</button>${!d.saleId&&!received(d)?`<button class="ghost small" onclick="cancelDebt(${d.id})">Cancelar</button>`:''}</td></tr>`))}</div>`}
function debtForm(){modal('Lançar fiado','Para saldo anterior ou uma dívida avulsa. Vendas do PDV geram o fiado automaticamente.',`<form onsubmit="event.preventDefault();saveDebt()"><div class="grid equal"><label>Cliente<select id="dCustomer" required>${customerOptions('',true)}</select></label>${field('Valor (R$)','dValue','','number','required min="0.01" step="0.01"')}${field('Descrição','dDesc','','text','required')}${field('Vencimento','dDue',today(),'date','required')}</div>${formEnd('Registrar fiado')}`)}
async function saveDebt(){const c=db().customers.find(c=>c.id===Number($('dCustomer').value)),v=round($('dValue').value);if(!c||!Number.isFinite(v)||v<=0)return toast('Cliente ou valor inválido.');if(c.limit&&customerBalance(c.id)+v>c.limit)return toast('Limite de crédito excedido.');const n=clone(state);n.db.debts.push({id:uid(),customerId:c.id,date:now(),due:$('dDue').value,description:$('dDesc').value,value:v,manual:true});if(await save(n,'Fiado manual: '+c.name)){closeModal();render()}}
async function cancelDebt(id){if(!confirm('Cancelar este fiado manual?'))return;const n=clone(state),d=n.db.debts.find(d=>d.id===id);if(d.saleId||received(d))return toast('Não é possível cancelar um fiado com recebimentos.');d.cancelled=true;if(await save(n,'Fiado manual cancelado'))render()}
function receiptForm(id){const d=db().debts.find(d=>d.id===id);modal('Receber fiado',esc(d.description)+' • Saldo: '+money(balance(d)),`<form onsubmit="event.preventDefault();saveReceipt(${id})"><div class="grid equal">${field('Valor recebido (R$)','rValue',balance(d),'number',`required min="0.01" max="${balance(d)}" step="0.01"`)}${select('Forma de recebimento','rMethod',[['Dinheiro','Dinheiro'],['Pix','Pix'],['Cartão','Cartão']])}</div>${formEnd('Confirmar recebimento')}`)}
async function saveReceipt(id){const d=db().debts.find(d=>d.id===id),v=round($('rValue').value);if(d.cancelled||!Number.isFinite(v)||v<=0||v>balance(d))return toast('Valor superior ao saldo ou inválido.');const n=clone(state);n.db.receipts.push({id:uid(),debtId:id,customerId:d.customerId,date:now(),value:v,payment:$('rMethod').value});if(await save(n,'Recebimento de fiado: '+money(v))){closeModal();render()}}
function customerStatement(id,print=false){const c=db().customers.find(c=>c.id===id),debts=db().debts.filter(d=>d.customerId===id&&!d.cancelled),receipts=db().receipts.filter(r=>r.customerId===id&&!r.cancelled);const html=`<h2>${esc(c.name)}</h2><p class="subtitle">${esc(c.document||'')} • ${esc(c.phone||'')}</p>${line('Saldo em aberto',money(customerBalance(id)),true)}<h3 style="margin:20px 0">Lançamentos</h3>${table(['Data','Descrição','Vencimento','Valor','Saldo'],debts.map(d=>`<tr><td>${date(d.date)}</td><td>${esc(d.description)}</td><td>${date(d.due)}</td><td>${money(d.value)}</td><td>${money(balance(d))}</td></tr>`))}<h3 style="margin:20px 0">Recebimentos</h3>${table(['Data','Forma','Valor'],receipts.map(r=>`<tr><td>${date(r.date)}</td><td>${esc(r.payment)}</td><td>${money(r.value)}</td></tr>`))}`;if(print)return printDocument('Extrato de fiado',html);modal('Extrato do cliente','Posição atual da conta.',html+`<div class="form-actions"><button onclick="customerStatement(${id},true)">Imprimir / PDF</button></div>`)}
function suppliersView(){return head('Fornecedores','Cadastros prontos para suas notas de entrada.',`<button onclick="supplierForm()">+ Novo fornecedor</button>`)+`<div class="card">${table(['Fornecedor','CNPJ / CPF','Contato','Endereço','Ações'],db().suppliers.map(s=>`<tr><td><b>${esc(s.name)}</b><small>${esc(s.contact||'')}</small></td><td>${esc(s.document)}</td><td>${esc(s.phone)}<small>${esc(s.email)}</small></td><td>${esc(s.address)}</td><td><button class="ghost small" onclick="supplierForm(${s.id})">Editar</button></td></tr>`))}</div>`}
function supplierForm(id){const s=db().suppliers.find(s=>s.id===id)||{};modal(id?'Editar fornecedor':'Novo fornecedor','Estas informações serão recuperadas no cadastro da NF.',`<form onsubmit="event.preventDefault();saveSupplier(${id||0})"><div class="grid equal">${field('Razão social / nome','sName',s.name,'text','required')}${field('CNPJ / CPF','sDoc',s.document,'text','required')}${field('Pessoa de contato','sContact',s.contact)}${field('Telefone','sPhone',s.phone)}${field('E-mail','sEmail',s.email,'email')}${field('Endereço','sAddress',s.address)}</div>${formEnd()}`)}
async function saveSupplier(id){const s={id:id||uid(),name:$('sName').value.trim(),document:$('sDoc').value.trim(),contact:$('sContact').value.trim(),phone:$('sPhone').value.trim(),email:$('sEmail').value.trim(),address:$('sAddress').value.trim()};if(!s.name||!s.document)return toast('Informe nome e documento.');if(db().suppliers.some(x=>x.id!==id&&x.document.replace(/\D/g,'')===s.document.replace(/\D/g,'')))return toast('Fornecedor com este documento já cadastrado.');const n=clone(state);if(id)Object.assign(n.db.suppliers.find(x=>x.id===id),s);else n.db.suppliers.push(s);if(await save(n,'Fornecedor: '+s.name)){closeModal();render()}}
function invoicesView(){return head('Notas de entrada','Registre compras, atualize o estoque e acompanhe o pagamento.',`<button onclick="invoiceForm()">+ Registrar NF</button>`)+`<div class="card">${table(['Nota / chave','Fornecedor','Data','Total','Financeiro','Ações'],db().invoices.slice().reverse().map(n=>`<tr><td><b>NF ${esc(n.number)}</b><small>${esc(n.key||'Sem chave informada')}</small></td><td>${esc(n.supplier)}</td><td>${date(n.date)}</td><td>${money(n.total)}</td><td><span class="badge ${n.legacy?'warn':'neutral'}">${n.legacy?'Legado • conciliar':'Conta gerada'}</span></td><td><button class="ghost small" onclick="invoiceDetail(${n.id})">Detalhes</button></td></tr>`))}</div>`}
function invoiceForm(){nfLines=[];nfXML='';nfTotal=null;modal('Registrar nota de entrada','Selecione o fornecedor e vincule cada item ao seu catálogo.',`<form onsubmit="event.preventDefault();saveInvoice()"><button type="button" class="secondary small" onclick="document.getElementById('nfXML').click()">Importar XML de NF-e</button><input type="file" id="nfXML" accept=".xml" hidden onchange="importXML(this.files[0])"><div class="grid equal" style="margin-top:18px">${select('Fornecedor','nfSupplier',[['','Selecione...'],...db().suppliers.map(s=>[s.id,s.name])])}${field('Número da nota','nfNumber','','text','required')}${field('Emissão','nfDate',today(),'date','required')}${field('Vencimento','nfDue',today(),'date','required')}${field('Chave de acesso (44 dígitos)','nfKey','','text','pattern="[0-9]{44}" maxlength="44"')}${select('Pagamento','nfPaid',[['pending','A pagar'],['paid','Já paga']])}${select('Forma de pagamento','nfMethod',[['Dinheiro','Dinheiro'],['Pix','Pix'],['Cartão','Cartão'],['Transferência','Transferência']])}${field('Total da NF (R$)','nfValue','','number','required min="0.01" step="0.01"')}</div><div id="nfSupplierInfo" class="notice">O cadastro do fornecedor será vinculado à nota.</div><h3 style="margin:18px 0 10px">Itens da nota</h3><div class="grid" style="grid-template-columns:2fr 1fr 1fr auto;gap:7px"><select id="nfProduct"><option value="">Produto</option>${db().products.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><input id="nfQty" type="number" min="0.001" step="0.001" placeholder="Qtd. / KG"><input id="nfCost" type="number" min="0" step="0.01" placeholder="Custo"><button type="button" onclick="addNFLine()">+</button></div><div id="nfLines"></div><p class="muted" style="font-size:11px;margin-top:14px">O total da nota gera uma conta de compra. O custo informado por item atualiza o custo médio do estoque. Frete, impostos e descontos do XML devem ser conferidos antes de gravar.</p>${formEnd('Gravar nota e estoque')}`);$('nfSupplier').onchange=()=>{const s=db().suppliers.find(s=>String(s.id)===$('nfSupplier').value);$('nfSupplierInfo').textContent=s?[s.name,s.document,s.phone,s.address].filter(Boolean).join(' • '):'Selecione um fornecedor.'}}
function addNFLine(){const p=db().products.find(p=>p.id===Number($('nfProduct').value)),qty=Number($('nfQty').value),cost=Number($('nfCost').value);if(!p||!validQty(p,qty)||!Number.isFinite(cost)||cost<0)return toast('Confira produto, quantidade na unidade cadastrada e custo.');nfLines.push({product:p.id,name:p.name,unit:p.unit,qty,cost:round(cost)});renderNFLines();$('nfQty').value='';$('nfCost').value=''}
function renderNFLines(){const sum=round(nfLines.reduce((a,i)=>a+i.qty*i.cost,0));$('nfLines').innerHTML=table(['Produto','Qtd.','Custo','Total',''],nfLines.map((i,n)=>`<tr><td>${i.product?esc(i.name):`<select onchange="nfLines[${n}].product=Number(this.value);nfLines[${n}].name=db().products.find(p=>p.id===Number(this.value))?.name||nfLines[${n}].name;nfLines[${n}].unit=db().products.find(p=>p.id===Number(this.value))?.unit;renderNFLines()"><option value="">Vincular: ${esc(i.name)}</option>${db().products.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select>`}</td><td>${i.qty} ${esc(i.unit||'UN')}</td><td>${money(i.cost)}</td><td>${money(i.qty*i.cost)}</td><td><button type="button" class="ghost" onclick="nfLines.splice(${n},1);renderNFLines()">×</button></td></tr>`))+line('Total dos itens',money(sum),true);if(!nfXML)$('nfValue').value=sum}
async function importXML(file){if(!file)return;try{if(file.size>4e6)throw Error('XML maior que 4 MB.');const text=await file.text(),xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror')||!xml.querySelector('infNFe'))throw Error('Selecione um XML de NF-e válido.');const get=(node,tag)=>node?.getElementsByTagName(tag)?.[0]?.textContent||'',emit=xml.querySelector('emit'),document=get(emit,'CNPJ')||get(emit,'CPF');let supplier=db().suppliers.find(s=>s.document.replace(/\D/g,'')===document);if(!supplier){if(!confirm('Cadastrar o fornecedor '+get(emit,'xNome')+' a partir do XML?'))return;const n=clone(state);supplier={id:uid(),name:get(emit,'xNome'),document,phone:get(emit,'fone'),address:[get(emit,'xLgr'),get(emit,'nro'),get(emit,'xMun'),get(emit,'UF')].join(', ')};n.db.suppliers.push(supplier);if(!await save(n,'Fornecedor importado do XML'))return;$('nfSupplier').insertAdjacentHTML('beforeend',`<option value="${supplier.id}">${esc(supplier.name)}</option>`)}$('nfSupplier').value=supplier.id;$('nfSupplier').onchange();$('nfNumber').value=get(xml,'nNF');$('nfKey').value=xml.querySelector('infNFe').getAttribute('Id')?.replace(/^NFe/,'')||'';$('nfDate').value=(get(xml,'dhEmi')||get(xml,'dEmi')).slice(0,10);$('nfDue').value=get(xml,'dVenc')||$('nfDate').value;$('nfValue').value=get(xml.querySelector('ICMSTot'),'vNF');nfLines=Array.from(xml.getElementsByTagName('det')).map(d=>{const prod=d.querySelector('prod'),barcode=get(prod,'cEAN'),p=db().products.find(p=>p.active&&p.barcode&&p.barcode===barcode);return{product:p?.id||null,name:p?.name||get(prod,'xProd'),unit:p?.unit,sourceUnit:get(prod,'uCom'),qty:Number(get(prod,'qCom')),cost:round(Number(get(prod,'vUnCom'))),ncm:get(prod,'NCM'),cfop:get(prod,'CFOP'),supplierCode:get(prod,'cProd')}});nfXML=text;renderNFLines();toast('XML lido. Confira valores e vincule os produtos não reconhecidos.')}catch(e){toast(e.message)}}
async function saveInvoice(){const s=db().suppliers.find(s=>s.id===Number($('nfSupplier').value)),number=$('nfNumber').value.trim(),key=$('nfKey').value.trim(),value=round($('nfValue').value),dateValue=$('nfDate').value;if(!s||!number||!nfLines.length||!Number.isFinite(value)||value<=0)return toast('Informe fornecedor, número, itens e total.');if(key&&!/^\d{44}$/.test(key))return toast('A chave precisa de 44 dígitos.');if(db().invoices.some(n=>key?n.key===key:n.supplierId===s.id&&n.number===number))return toast('Esta nota já foi cadastrada.');if(nfLines.some(i=>i.sourceUnit&&i.product&&i.sourceUnit.toUpperCase()!==db().products.find(p=>p.id===i.product)?.unit))return toast('Unidade do XML diferente do cadastro. Faça a entrada manual com quantidade e custo convertidos.');if(nfLines.some(i=>!i.product||!validQty(db().products.find(p=>p.id===i.product),i.qty)||!Number.isFinite(i.cost)||i.cost<0))return toast('Vincule os produtos e confira a unidade: KG admite 3 casas decimais; UN, CX e PCT exigem inteiros. Converta a unidade da NF para a unidade cadastrada antes de lançar.');const n=clone(state);for(const i of nfLines){const p=n.db.products.find(p=>p.id===i.product);if(!p)return toast('Produto não encontrado.');p.cost=round((p.cost*p.stock+i.qty*i.cost)/(p.stock+i.qty));p.stock=quantityRound(p.stock+i.qty)}const id=uid(),invoice={id,number,key,supplier:s.name,supplierId:s.id,supplierDocument:s.document,date:dateValue,due:$('nfDue').value,total:value,items:clone(nfLines),xml:nfXML};n.db.invoices.push(invoice);const paid=$('nfPaid').value==='paid';n.db.bills.push({id:uid(),type:'payable',category:'Compra de estoque',description:'NF '+number+' • '+s.name,value,date:dateValue,due:$('nfDue').value,invoiceId:id,supplierId:s.id,payments:paid?[{id:uid(),date:today(),value,payment:$('nfMethod').value}]:[]});if(await save(n,'Entrada NF '+number)){closeModal();render();toast('Nota, estoque e conta registrados.')}}
function invoiceDetail(id){const n=db().invoices.find(n=>n.id===id);modal('NF '+esc(n.number),esc(n.supplier),`${line('Documento do fornecedor',esc(n.supplierDocument||'—'))}${line('Chave',esc(n.key||'—'))}${line('Total',money(n.total),true)}${table(['Produto','Quantidade','Custo unitário'],n.items.map(i=>`<tr><td>${esc(i.name||db().products.find(p=>p.id===i.product)?.name||'Produto')}</td><td>${i.qty} ${esc(i.unit||'UN')}</td><td>${money(i.cost)}</td></tr>`))}${n.xml?`<div class="form-actions"><button onclick="download('NF-${esc(n.number)}.xml',db().invoices.find(n=>n.id===${id}).xml,'application/xml')">Baixar XML original</button></div>`:''}`)}
function cashRows(){let rows=[];for(const s of db().sales)if(s.payment!=='Fiado'){rows.push({date:s.date,type:'Entrada',category:'Venda',description:'Venda #'+s.id,party:s.customerName||'Consumidor',payment:s.payment,value:s.total,ref:'VENDA-'+s.id});if(s.status==='cancelled')rows.push({date:s.cancelledAt||s.date,type:'Saída',category:'Estorno de venda',description:'Cancelamento #'+s.id,party:s.customerName||'Consumidor',payment:s.payment,value:s.total,ref:'ESTORNO-'+s.id});}for(const r of db().receipts.filter(r=>!r.cancelled))rows.push({date:r.date,type:'Entrada',category:'Recebimento de fiado',description:'Fiado #'+r.debtId,party:db().customers.find(c=>c.id===r.customerId)?.name||'',payment:r.payment,value:r.value,ref:'REC-'+r.id});for(const e of db().exits.filter(e=>e.type==='expense'&&!e.cancelled))rows.push({date:e.date,type:'Saída',category:'Despesa legada',description:e.desc,party:'',payment:e.payment||'Não informado',value:e.value,ref:'DESP-'+e.id});for(const b of db().bills.filter(b=>!b.cancelled))for(const p of b.payments||[])rows.push({date:p.date,type:b.type==='payable'?'Saída':'Entrada',category:b.category,description:b.description,party:db().suppliers.find(s=>s.id===b.supplierId)?.name||'',payment:p.payment,value:p.value,ref:'CONTA-'+b.id});return rows.sort((a,b)=>a.date.localeCompare(b.date))}
function financeData(m){const sales=db().sales.filter(s=>localDay(s.date).startsWith(m)),reversals=db().sales.filter(s=>s.status==='cancelled'&&localDay(s.cancelledAt||s.date).startsWith(m)),cash=cashRows().filter(r=>localDay(r.date).startsWith(m)),revenue=round(sales.reduce((a,s)=>a+s.total,0)-reversals.reduce((a,s)=>a+s.total,0)),cogs=round(sales.reduce((a,s)=>a+s.items.reduce((a,i)=>a+i.cost*i.qty,0),0)-reversals.reduce((a,s)=>a+s.items.reduce((a,i)=>a+i.cost*i.qty,0),0)),loss=round(db().exits.filter(e=>e.type==='loss'&&!e.cancelled&&localDay(e.date).startsWith(m)).reduce((a,e)=>a+e.value,0)),expenses=round(db().exits.filter(e=>e.type==='expense'&&!e.cancelled&&localDay(e.date).startsWith(m)).reduce((a,e)=>a+e.value,0)+db().bills.filter(b=>!b.cancelled&&b.type==='payable'&&!['Compra de estoque','Investimento','Transferência'].includes(b.category)&&localDay(b.date).startsWith(m)).reduce((a,b)=>a+b.value,0)),income=round(cash.filter(r=>r.type==='Entrada').reduce((a,r)=>a+r.value,0)),out=round(cash.filter(r=>r.type==='Saída').reduce((a,r)=>a+r.value,0));return{sales,cash,revenue,cogs,loss,expenses,income,out,profit:round(revenue-cogs-loss-expenses),net:round(income-out)}}
function financeView(){const d=financeData(filterMonth),bills=db().bills.filter(b=>!b.cancelled),openPay=round(bills.filter(b=>b.type==='payable').reduce((a,b)=>a+b.value-billPaid(b),0)),openReceive=round(bills.filter(b=>b.type==='receivable').reduce((a,b)=>a+b.value-billPaid(b),0));return head('Financeiro','Competência e caixa separados para você decidir com segurança.',`<button class="secondary" onclick="reportDialog()">Relatórios para contador</button><button onclick="billForm()">+ Lançamento</button>`)+`<div class="toolbar"><label>Período<input type="month" value="${filterMonth}" onchange="filterMonth=this.value||month();render()"></label><button class="secondary small" onclick="financeReport()">Imprimir resumo / PDF</button></div><div class="grid kpis">${kpi('Entradas de caixa',money(d.income),'Recebimentos no período')}${kpi('Saídas de caixa',money(d.out),'Pagamentos no período')}${kpi('Movimento líquido',money(d.net),'Entradas − saídas; não é saldo bancário')}${kpi('Resultado gerencial',money(d.profit),'Receita − CMV − perdas − despesas')}</div><div class="grid equal"><div class="card"><div class="card-head"><h3>Resultado por competência</h3><span class="badge neutral">${esc(filterMonth)}</span></div>${line('Receita de vendas (inclui fiado)',money(d.revenue))}${line('Custo das mercadorias vendidas',money(d.cogs))}${line('Perdas de estoque',money(d.loss))}${line('Despesas do período',money(d.expenses))}${line('Resultado operacional gerencial',money(d.profit),true)}<p class="muted" style="font-size:10px;margin-top:14px">Tributos e taxas só entram quando lançados. Recebimentos de fiado não duplicam a receita. Compras de estoque não são despesa operacional.</p></div><div class="card"><h3>Compromissos em aberto</h3>${line('Contas a pagar',money(openPay),true)}${line('Contas a receber',money(openReceive))}${line('Fiado a receber',money(db().debts.reduce((a,d)=>a+balance(d),0)))}<p class="notice">Saldos atuais de todos os períodos. Contas legadas de NF precisam de conciliação manual.</p><button class="secondary full" onclick="location.hash='fiado'">Consultar carteira de fiado →</button></div></div><div class="card" style="margin-top:22px"><div class="card-head"><h3>Contas a pagar e receber</h3><span class="muted">Todas as competências</span></div>${table(['Descrição / categoria','Tipo','Competência','Vencimento','Valor','Em aberto','Ações'],bills.slice().sort((a,b)=>a.due.localeCompare(b.due)).map(b=>`<tr><td><b>${esc(b.description)}</b><small>${esc(b.category)}</small></td><td>${b.type==='payable'?'A pagar':'A receber'}</td><td>${date(b.date)}</td><td><span class="badge ${b.value>billPaid(b)&&b.due<today()?'red':'neutral'}">${date(b.due)}</span></td><td>${money(b.value)}</td><td><b>${money(b.value-billPaid(b))}</b></td><td>${b.value>billPaid(b)?`<button class="ghost small" onclick="billPaymentForm(${b.id})">Baixar</button>`:'<span class="badge">Quitada</span>'}${!billPaid(b)&&!b.invoiceId?`<button class="ghost small" onclick="billForm(${b.id})">Editar</button><button class="ghost small" onclick="cancelBill(${b.id})">Cancelar</button>`:''}</td></tr>`))}</div><div class="card" style="margin-top:22px"><div class="card-head"><h3>Movimentações de caixa</h3><button class="ghost" onclick="exportAccounting('caixa')">Exportar CSV ↓</button></div>${cashTable(d.cash)}</div>`}
function cashTable(rows){return table(['Data','Tipo','Descrição','Categoria','Forma','Valor'],rows.map(r=>`<tr><td>${date(r.date)}</td><td><span class="badge ${r.type==='Saída'?'red':''}">${r.type}</span></td><td>${esc(r.description)}</td><td>${esc(r.category)}</td><td>${esc(r.payment)}</td><td><b>${money(r.value)}</b></td></tr>`))}
const categories=['Despesa operacional','Aluguel','Energia / água','Pessoal','Tributos','Taxas de cartão','Compra de estoque','Investimento','Transferência','Outras receitas'];
function billForm(id){const b=db().bills.find(b=>b.id===id)||{date:today(),due:today(),value:'',type:'payable',category:'Despesa operacional'};modal(id?'Editar lançamento':'Novo lançamento','Pagamentos e recebimentos são registrados separadamente na baixa.',`<form onsubmit="event.preventDefault();saveBill(${id||0})"><div class="grid equal">${select('Tipo','bType',[['payable','Conta a pagar'],['receivable','Conta a receber']],b.type)}${select('Categoria','bCategory',categories.map(c=>[c,c]),b.category)}${field('Descrição','bDesc',b.description,'text','required')}${field('Valor (R$)','bValue',b.value,'number','required min="0.01" step="0.01"')}${field('Competência / emissão','bDate',b.date,'date','required')}${field('Vencimento','bDue',b.due,'date','required')}</div>${formEnd()}`)}
async function saveBill(id){const b={id:id||uid(),type:$('bType').value,category:$('bCategory').value,description:$('bDesc').value.trim(),value:round($('bValue').value),date:$('bDate').value,due:$('bDue').value,payments:[]};if(!b.description||!Number.isFinite(b.value)||b.value<=0)return toast('Dados inválidos.');const n=clone(state);if(id){const old=n.db.bills.find(b=>b.id===id);if(old.invoiceId||billPaid(old))return toast('Conta vinculada ou com pagamento não pode ser editada.');Object.assign(old,b)}else n.db.bills.push(b);if(await save(n,'Conta: '+b.description)){closeModal();render()}}
async function cancelBill(id){if(!confirm('Cancelar este lançamento?'))return;const n=clone(state),b=n.db.bills.find(b=>b.id===id);if(b.invoiceId||billPaid(b))return toast('Conta vinculada ou com pagamento não pode ser cancelada.');b.cancelled=true;if(await save(n,'Conta cancelada: '+b.description))render()}
function billPaymentForm(id){const b=db().bills.find(b=>b.id===id);modal(b.type==='payable'?'Registrar pagamento':'Registrar recebimento',esc(b.description),`<form onsubmit="event.preventDefault();billPaymentSave(${id})"><div class="grid equal">${field('Valor (R$)','bpValue',round(b.value-billPaid(b)),'number',`required min="0.01" max="${round(b.value-billPaid(b))}" step="0.01"`)}${field('Data da movimentação','bpDate',today(),'date','required')}${select('Forma','bpMethod',[['Dinheiro','Dinheiro'],['Pix','Pix'],['Cartão','Cartão'],['Transferência','Transferência']])}</div>${formEnd('Confirmar baixa')}`)}
async function billPaymentSave(id){const n=clone(state),b=n.db.bills.find(b=>b.id===id),v=round($('bpValue').value);if(b.cancelled||!Number.isFinite(v)||v<=0||v>round(b.value-billPaid(b)))return toast('Valor inválido ou superior ao saldo.');b.payments.push({id:uid(),date:$('bpDate').value,payment:$('bpMethod').value,value:v});if(await save(n,'Baixa: '+b.description+' • '+money(v))){closeModal();render()}}
function salesTable(sales){return table(['Venda / cliente','Data','Pagamento','Total','Status',''],sales.map(s=>`<tr><td><b>#${s.id}</b><small>${esc(s.customerName||'Consumidor')}</small></td><td>${date(s.date)}</td><td>${esc(s.payment)}</td><td><b>${money(s.total)}</b></td><td><span class="badge ${s.status==='cancelled'?'red':''}">${s.status==='cancelled'?'Cancelada':'Concluída'}</span></td><td><button class="ghost small" onclick="saleDetail(${s.id})">Ver</button></td></tr>`))}
function salesView(){return head('Histórico de vendas','Rastreabilidade de cada venda e dos seus cancelamentos.')+`<div class="card"><div class="toolbar"><label>Período<input type="month" value="${filterMonth}" onchange="filterMonth=this.value||month();render()"></label></div>${salesTable(db().sales.filter(s=>localDay(s.date).startsWith(filterMonth)).slice().reverse())}</div>`}
function saleDetail(id){const s=db().sales.find(s=>s.id===id);modal('Venda #'+id,esc(s.customerName||'Consumidor não identificado')+' • '+date(s.date),`${table(['Item','Qtd.','Unitário','Total'],s.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty} ${esc(i.unit||'UN')}</td><td>${money(i.price)}</td><td>${money(i.qty*i.price)}</td></tr>`))}${line('Forma',esc(s.payment))}${line('Total',money(s.total),true)}<div class="form-actions">${s.status!=='cancelled'?`<button class="danger" onclick="cancelSale(${id})">Cancelar venda</button>`:''}<button onclick="silentPrint(${id},true)">Imprimir na térmica</button><button class="secondary" onclick="printSale(${id})">Visualizar / PDF</button></div>`)}
async function cancelSale(id){const s=db().sales.find(s=>s.id===id),debt=db().debts.find(d=>d.saleId===id);if(s.status==='cancelled')return;if(debt&&received(debt)>0)return toast('Esta venda tem recebimentos de fiado. O cancelamento requer conciliar a devolução antes.');if(!confirm('Cancelar a venda #'+id+' e estornar o estoque? Para uma venda paga, confirme somente após devolver o valor integral ao cliente; o sistema registrará a saída de caixa.'))return;const n=clone(state),sale=n.db.sales.find(s=>s.id===id);sale.status='cancelled';sale.cancelledAt=now();for(const i of sale.items){const p=n.db.products.find(p=>p.id===i.product);if(p)p.stock=quantityRound(p.stock+i.qty)}if(debt)n.db.debts.find(d=>d.id===debt.id).cancelled=true;if(await save(n,'Cancelamento da venda #'+id)){closeModal();render();toast('Venda cancelada e estoque estornado.')}}
function printDocument(title,content){$('printArea').innerHTML=`<div class="receipt"><h1>${esc(cfg().name)}</h1><p><small>${esc(cfg().cnpj)} • ${esc(cfg().address)} • ${esc(cfg().phone)}</small></p><h2 style="margin:20px 0">${esc(title)}</h2>${content}<div class="footnote">KLSistemas ${VERSION} • Emitido em ${new Date().toLocaleString('pt-BR')}</div></div>`;if(!window.__reportCapture)window.print()}
function printSale(id){const s=db().sales.find(s=>s.id===id);printDocument('Comprovante não fiscal • Venda #'+id,`<p>${date(s.date)} • ${esc(s.customerName||'Consumidor não identificado')} ${s.status==='cancelled'?'• CANCELADA':''}</p>${table(['Descrição','Qtd.','Unitário','Total'],s.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty} ${esc(i.unit||'UN')}</td><td>${money(i.price)}</td><td>${money(i.qty*i.price)}</td></tr>`))}${line('Total',money(s.total),true)}${line('Forma de pagamento',esc(s.payment))}${s.cash!==null&&s.cash!==undefined?line('Recebido / troco',money(s.cash)+' / '+money(s.change)):''}<p style="margin-top:25px">${esc(cfg().receipt)}</p>`)}
function reportDialog(){modal('Relatórios para o contador','Período: '+filterMonth+' • CSV em UTF-8 com separador ponto e vírgula.',`<div class="notice">Relatórios gerenciais e documentos de apoio. Não substituem escrituração fiscal, SPED ou emissão de NF-e. Cadastre CNPJ e dados da empresa em Personalização.</div><button class="full" style="margin-bottom:18px" onclick="accountantPackage()">Baixar pacote completo (.zip)</button><div class="grid equal">${[['caixa','Livro de caixa'],['vendas','Vendas e itens'],['contas','Contas e saldos atuais'],['fiado','Fiados e recebimentos'],['notas','Notas de entrada'],['estoque','Inventário atual'],['auditoria','Registro de alterações']].map(([id,label])=>`<button class="secondary" onclick="exportAccounting('${id}')">${label} ↓ CSV</button>`).join('')}<button onclick="financeReport()">Resumo financeiro / PDF</button></div>`)}
function csvCell(x){let v=String(x??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}
function download(name,content,type='text/plain'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function exportAccounting(type,asData=false){let rows=[];const m=filterMonth,decimal=n=>round(n).toFixed(2).replace('.',',');if(type==='caixa')rows=[['Data','Tipo','Categoria','Descricao','Parte','Forma','Valor','Referencia'],...financeData(m).cash.map(r=>[localDay(r.date),r.type,r.category,r.description,r.party,r.payment,decimal(r.value),r.ref])];if(type==='vendas')rows=[['Venda','Data','Cliente','Pagamento','Status','Produto','Codigo','Quantidade','Unidade','Preco unitario','Custo unitario','Total item','Total venda','Cancelamento'],...db().sales.filter(s=>localDay(s.date).startsWith(m)).flatMap(s=>s.items.map(i=>[s.id,localDay(s.date),s.customerName,s.payment,s.status,i.name,db().products.find(p=>p.id===i.product)?.barcode||'AVULSO',i.qty,i.unit||'UN',decimal(i.price),decimal(i.cost),decimal(i.qty*i.price),decimal(s.total),s.cancelledAt||'']))];if(type==='contas')rows=[['Tipo','Descricao','Categoria','Competencia','Vencimento','Valor','Pago','Saldo','Status'],...db().bills.map(b=>[b.type,b.description,b.category,b.date,b.due,decimal(b.value),decimal(billPaid(b)),decimal(b.value-billPaid(b)),b.cancelled?'Cancelada':'Ativa'])];if(type==='fiado')rows=[['Tipo','ID','Cliente','Data','Vencimento','Descricao','Valor','Saldo atual','Status'],...db().debts.map(d=>['Divida',d.id,db().customers.find(c=>c.id===d.customerId)?.name,localDay(d.date),d.due,d.description,decimal(d.value),decimal(balance(d)),d.cancelled?'Cancelada':'Ativa']),...db().receipts.map(r=>['Recebimento',r.id,db().customers.find(c=>c.id===r.customerId)?.name,localDay(r.date),'','Divida '+r.debtId+' - '+r.payment,decimal(r.value),'',r.cancelled?'Cancelado':'Ativo'])];if(type==='notas')rows=[['Numero','Emissao','Fornecedor','Documento','Chave','Total NF','Produto','Quantidade','Unidade','Custo','NCM','CFOP'],...db().invoices.filter(n=>localDay(n.date).startsWith(m)).flatMap(n=>n.items.map(i=>[n.number,localDay(n.date),n.supplier,n.supplierDocument,n.key,decimal(n.total),i.name||db().products.find(p=>p.id===i.product)?.name,i.qty,i.unit||'UN',decimal(i.cost),i.ncm,i.cfop]))];if(type==='estoque')rows=[['Produto','Codigo','Categoria','Unidade','Quantidade','Custo unitario','Custo total','Preco venda','Ativo'],...db().products.map(p=>[p.name,p.barcode,p.category,p.unit,p.stock,decimal(p.cost),decimal(p.stock*p.cost),decimal(p.price),p.active?'Sim':'Nao'])];if(type==='auditoria')rows=[['Data hora','Acao'],...db().audit.filter(a=>localDay(a.date).startsWith(m)).map(a=>[a.date,a.action])];const metadata=[['Empresa',cfg().name],['CNPJ',cfg().cnpj],['Periodo',m],['Emitido em',new Date().toLocaleString('pt-BR')],['Observacao',['contas','fiado','estoque'].includes(type)?'Posicao atual de todos os periodos':'Movimentacoes do periodo'],[]];const content='\uFEFF'+[...metadata,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n');if(asData)return content;download(`KLSistemas_${type}_${m}.csv`,content,'text/csv;charset=utf-8');toast('CSV exportado.')}
function financeReport(){const d=financeData(filterMonth);printDocument('Resumo financeiro • '+filterMonth,`<h3>Competência</h3>${line('Receita de vendas',money(d.revenue))}${line('CMV',money(d.cogs))}${line('Perdas de estoque',money(d.loss))}${line('Despesas',money(d.expenses))}${line('Resultado gerencial',money(d.profit),true)}<h3 style="margin-top:24px">Fluxo de caixa</h3>${line('Entradas',money(d.income))}${line('Saídas',money(d.out))}${line('Movimento líquido',money(d.net),true)}<h3 style="margin-top:24px">Detalhamento de caixa</h3>${cashTable(d.cash)}<p class="footnote">Relatório gerencial. Movimento líquido não representa saldo bancário. Compras de estoque afetam caixa quando pagas e resultado via CMV quando vendidas. Fiados afetam receita na venda e caixa no recebimento. Tributos, taxas, depreciação e demais ajustes dependem dos lançamentos e da validação do contador. Saldos manuais anteriores de fiado não geram nova receita neste relatório.</p>`)}
function settingsView(){return head('Personalização','Sua identidade, sua operação, do seu jeito.')+`<form onsubmit="event.preventDefault();saveSettings()"><div class="grid equal"><div class="card"><h3>Identidade da empresa</h3><div class="grid equal" style="margin-top:22px">${field('Nome da loja','setName',cfg().name,'text','required')}${field('CNPJ / CPF','setCnpj',cfg().cnpj)}${field('Endereço','setAddress',cfg().address)}${field('Telefone','setPhone',cfg().phone)}</div><label style="margin-top:18px">Logo (PNG, JPEG, WebP • até 1 MB)<input id="setLogo" type="file" accept="image/png,image/jpeg,image/webp"></label><label style="margin-top:12px"><input id="removeLogo" type="checkbox"> Remover logo atual</label><h3 style="margin-top:25px">Comprovante de venda</h3><label style="margin-top:15px">Mensagem do rodapé<textarea id="setReceipt">${esc(cfg().receipt)}</textarea></label><label style="margin-top:14px"><input id="setAutoPrint" type="checkbox" ${cfg().autoPrint?'checked':''}> Imprimir automaticamente na térmica ao finalizar</label><div class="grid equal" style="margin-top:16px"><label>Impressora do Windows<select id="setPrinter"><option value="">Padrão do Windows</option>${cfg().printerName?`<option selected value="${esc(cfg().printerName)}">${esc(cfg().printerName)}</option>`:''}</select></label>${select('Largura da bobina','setReceiptWidth',[[58,'58 mm'],[80,'80 mm']],cfg().receiptWidth)}</div><div class="actions" style="margin-top:12px"><button type="button" class="secondary small" onclick="loadPrinters()">Atualizar lista</button><button type="button" class="secondary small" onclick="testPrinter()">Imprimir teste</button></div><p id="printerInfo" class="muted" style="font-size:11px;margin-top:10px">Carregando impressoras instaladas…</p></div><div class="card"><h3>Aparência</h3><div class="grid equal" style="margin-top:22px">${field('Cor principal','setColor',cfg().color,'color')}${select('Tamanho do texto','setFont',[[13,'Pequeno'],[14,'Padrão'],[16,'Grande']],cfg().font)}</div><div class="grid equal" style="margin-top:20px"><label><input id="setDark" type="checkbox" ${cfg().dark?'checked':''}> Tema escuro</label><label><input id="setCompact" type="checkbox" ${cfg().compact?'checked':''}> Layout compacto</label></div><h3 style="margin-top:28px">Menu lateral</h3><p class="muted" style="font-size:11px;margin:7px 0 12px">Renomeie, reordene ou oculte módulos. Personalização e Atualizações permanecem acessíveis.</p><div id="menuEditor"></div></div></div><div class="form-actions"><button type="submit">Salvar personalização</button></div></form><div class="card" style="margin-top:24px"><div class="card-head"><h3>Dados e segurança</h3><span class="badge">Backup JSON</span></div><p class="muted" style="font-size:12px;margin-bottom:18px">Armazenamento neste computador. Exporte uma cópia para outro dispositivo regularmente. A importação substitui os dados atuais após a confirmação.</p><div class="actions"><button class="secondary" onclick="exportBackup()">Exportar backup completo</button><button class="secondary" onclick="$('backupFile').click()">Importar Ely / KLSistemas</button><input hidden id="backupFile" type="file" accept=".json" onchange="importBackup(this.files[0])"></div><p class="muted" style="font-size:10px;margin-top:14px">Pasta dos dados: ${esc(dataPath)}</p></div>`}
let menuDraft=[];
function renderMenuEditor(){menuDraft=clone(cfg().menu);paintMenu()}
function paintMenu(){$('menuEditor').innerHTML=menuDraft.map((m,i)=>`<div class="order-item"><input type="checkbox" ${m.visible?'checked':''} ${['settings','updates'].includes(m.id)?'disabled':''} onchange="menuDraft[${i}].visible=this.checked"><input aria-label="Nome do módulo" value="${esc(m.label)}" maxlength="28" onchange="menuDraft[${i}].label=this.value.trim()||'${m.id}'"><button type="button" class="ghost small" onclick="moveMenu(${i},-1)">↑</button><button type="button" class="ghost small" onclick="moveMenu(${i},1)">↓</button></div>`).join('')}
function moveMenu(i,d){const j=i+d;if(j<0||j>=menuDraft.length)return;[menuDraft[i],menuDraft[j]]=[menuDraft[j],menuDraft[i]];paintMenu()}
async function saveSettings(){const n=clone(state);Object.assign(n.settings,{name:$('setName').value.trim()||'Minha loja',cnpj:$('setCnpj').value,address:$('setAddress').value,phone:$('setPhone').value,color:$('setColor').value,font:Number($('setFont').value),dark:$('setDark').checked,compact:$('setCompact').checked,receipt:$('setReceipt').value,autoPrint:$('setAutoPrint').checked,printingVersion:1,printerName:$('setPrinter').value,receiptWidth:Number($('setReceiptWidth').value),menu:clone(menuDraft)});if($('removeLogo').checked)n.settings.logo='';const file=$('setLogo').files[0];if(file){if(file.size>1e6||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Use PNG, JPEG ou WebP com até 1 MB.');n.settings.logo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}if(await save(n,'Personalização atualizada')){render();toast('Personalização salva.')}}
function exportBackup(){download('KLSistemas_backup_'+today()+'.json',JSON.stringify({...state,exportedAt:now()},null,2),'application/json');toast('Backup exportado.')}
async function importBackup(file){if(!file)return;try{if(file.size>40e6)throw Error('Arquivo maior que 40 MB.');const n=normalize(JSON.parse(await file.text()));if(!confirm(`Importar ${n.db.products.length} produtos, ${n.db.sales.length} vendas e ${n.db.customers.length} clientes? Os dados atuais serão substituídos. Um backup dos dados atuais será baixado antes.`))return;exportBackup();if(await save(n,'Importação de backup '+file.name)){cart=[];render();toast('Backup importado. Confira saldos e notas legadas.')}}catch(e){toast('Falha na importação: '+e.message)}}
function updatesView(){if(hosted)return head('Atualizações','Versão online '+VERSION)+`<div class="card">As atualizações desta versão são publicadas pelo repositório GitHub e implantadas no Render. O EXE continua sendo usado para a operação local.</div>`;return head('Atualizações','Evolua o sistema mantendo seus dados neste computador.')+`<div class="grid equal"><div class="card"><span class="badge">Versão instalada ${VERSION}</span><h2 style="margin-top:18px">Receber novas versões</h2><p class="subtitle" style="font-size:12px;margin-bottom:22px">Configure o endereço publicado pelo responsável pelo sistema. O download é validado com SHA-256 antes da substituição do executável.</p>${field('URL HTTPS do manifesto','updateURL',cfg().updateManifestUrl,'url','placeholder="https://seu-dominio/updates.json"')}<div class="actions" style="margin-top:18px"><button class="secondary" onclick="saveUpdateURL()">Salvar endereço</button><button onclick="checkUpdate()">Verificar atualização</button></div><div id="updateResult" class="notice">Nenhum servidor de atualizações conectado. Os dados permanecem locais.</div></div><div class="card"><h3>Aplicar atualização por arquivo</h3><p class="subtitle" style="font-size:12px;margin:16px 0 22px">Recebeu um novo EXE do KLSistemas? Selecione o arquivo. O aplicativo fecha, preserva uma cópia do executável anterior e inicia a versão nova.</p><input id="updateFile" type="file" accept=".exe"><button style="margin-top:18px" onclick="applyLocalUpdate()">Aplicar novo EXE</button><div class="notice">Use apenas arquivos fornecidos por você ou pelo desenvolvedor do sistema. Exporte um backup antes de atualizar.</div><button class="secondary full" onclick="exportBackup()">Exportar backup agora</button></div></div>`}
async function saveUpdateURL(){const url=$('updateURL').value.trim();if(url&&!/^https:\/\//.test(url))return toast('Informe uma URL HTTPS.');const n=clone(state);n.settings.updateManifestUrl=url;if(await save(n,'Endereço de atualização alterado'))toast('Endereço salvo.')}
function compareVersion(a,b){const x=a.split('.').map(Number),y=b.split('.').map(Number);for(let i=0;i<3;i++){if(x[i]!==y[i])return Math.sign(x[i]-y[i])}return 0}
async function checkUpdate(){const url=$('updateURL').value.trim();if(!/^https:\/\//.test(url))return toast('Informe o endereço HTTPS do manifesto.');$('updateResult').textContent='Consultando…';try{const m=await api('/api/manifest',{url});if(!/^\d+\.\d+\.\d+$/.test(m.version)||!/^https:\/\//.test(m.exeUrl)||!/^[a-f0-9]{64}$/i.test(m.sha256))throw Error('Manifesto inválido: são necessários version, exeUrl e sha256.');updateManifest=m;$('updateResult').innerHTML=compareVersion(m.version,VERSION)>0?`Versão ${esc(m.version)} disponível.<p>${esc(m.notes||'')}</p><button style="margin-top:12px" onclick="applyRemoteUpdate()">Baixar e instalar</button>`:'Sua versão está atualizada.'}catch(e){$('updateResult').textContent=e.message}}
async function applyLocalUpdate(){const f=$('updateFile').files[0];if(!f||!f.name.toLowerCase().endsWith('.exe')||f.size>100e6)return toast('Selecione um EXE de até 100 MB.');if(!confirm('Aplicar '+f.name+'? O sistema será fechado. Confirme somente se você confia na origem deste arquivo.'))return;try{exportBackup();await api('/api/update/file',await f.arrayBuffer(),true);toast('Atualização iniciada. Aguarde a reabertura do aplicativo.')}catch(e){toast(e.message)}}
async function applyRemoteUpdate(){if(!updateManifest||!confirm('Instalar a versão '+updateManifest.version+' e reiniciar o KLSistemas?'))return;try{exportBackup();await api('/api/update/remote',{url:updateManifest.exeUrl,sha256:updateManifest.sha256});toast('Arquivo validado. Reiniciando para concluir a atualização.')}catch(e){toast(e.message)}}
document.addEventListener('keydown',e=>{if(page!=='pdv'||$('modal').open)return;if(e.key==='F2'){e.preventDefault();$('scan').focus()}if(e.key==='F4'){e.preventDefault();openVA()}if(e.key==='F9'){e.preventDefault();finalizeSale()}});
let printingSales=new Set();
async function loadPrinters(){try{const data=await api('/api/printers');if(!$('setPrinter'))return;const current=$('setPrinter').value;const names=Array.isArray(data.printers)?data.printers:[];$('setPrinter').innerHTML='<option value="">Padrão do Windows'+(data.defaultPrinter?' — '+esc(data.defaultPrinter):'')+'</option>'+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');if(current&&!names.includes(current))$('setPrinter').insertAdjacentHTML('beforeend',`<option value="${esc(current)}">${esc(current)} (indisponível)</option>`);$('setPrinter').value=current;$('printerInfo').textContent='Selecione a térmica física. O envio é direto, sem janela de impressão. O corte depende do driver.'}catch(e){if($('printerInfo'))$('printerInfo').textContent=e.message}}
async function testPrinter(){try{const n=clone(state);n.settings.printerName=$('setPrinter').value;n.settings.receiptWidth=Number($('setReceiptWidth').value);if(!await save(n,'Configuração da impressora'))return;await api('/api/print',{test:true,printer:n.settings.printerName,width:n.settings.receiptWidth});toast('Teste enviado à fila da impressora.')}catch(e){toast(e.message)}}
async function silentPrint(id,retry=false){if(printingSales.has(id))return;if(retry&&!confirm('Confira a fila e o papel antes de reimprimir a venda #'+id+'. Enviar outra cópia?'))return;printingSales.add(id);try{await api('/api/print',{saleId:id,retry});toast('Venda #'+id+': comprovante enviado à fila da impressora.');if($('printFeedback')){$('printFeedback').hidden=false;$('printFeedback').textContent='Venda #'+id+' salva. Comprovante enviado à fila de impressão.'}}catch(e){toast(e.message);if($('printFeedback')){$('printFeedback').hidden=false;$('printFeedback').innerHTML=`<b>Venda #${id} salva.</b> ${esc(e.message)} <button class="secondary small" onclick="silentPrint(${id},true)">Reimprimir</button>`}}finally{printingSales.delete(id)}}
async function boot(){try{const config=await api('/api/config');hosted=!!config.cloud;managedPortal=!!config.managed;const result=await api('/api/state');revision=result.revision;dataPath=result.dataDir;if(result.state)state=normalize(result.state);else{state.settings.name=result.companyName||'Minha empresa';state.settings.cnpj=result.companyDocument||''}ready=true;$('saveStatus').textContent=hosted?'✓ Dados da empresa salvos':'✓ Dados locais';navigate()}catch(e){if(hosted&&$('cloudLogin'))return;$('main').innerHTML=`<div class="card"><h2>Não foi possível abrir os dados</h2><p class="subtitle">${esc(e.message)}</p><button style="margin-top:20px" onclick="location.reload()">Tentar novamente</button></div>`}}
function zipFiles(files){
 const encoder=new TextEncoder(),chunks=[],central=[];let offset=0;const crc=b=>{let c=0xffffffff;for(const n of b){c^=n;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0};
 const header=(size)=>{const b=new Uint8Array(size);return[b,new DataView(b.buffer)]};
 for(const [name,content] of files){const filename=encoder.encode(name),data=encoder.encode(content),sum=crc(data),[h,v]=header(30);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,sum,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,filename.length,true);chunks.push(h,filename,data);const[c,w]=header(46);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x800,true);w.setUint32(16,sum,true);w.setUint32(20,data.length,true);w.setUint32(24,data.length,true);w.setUint16(28,filename.length,true);w.setUint32(42,offset,true);central.push(c,filename);offset+=h.length+filename.length+data.length}
 const length=central.reduce((a,x)=>a+x.length,0),[end,e]=header(22);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,length,true);e.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});
}
function accountantPackage(){const files=['caixa','vendas','contas','fiado','notas','estoque','auditoria'].map(t=>[t+'.csv',exportAccounting(t,true)]);window.__reportCapture=true;try{financeReport()}finally{window.__reportCapture=false}files.push(['resumo_financeiro.html','<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Resumo financeiro</title><style>body{font:14px Arial;margin:40px;color:#222}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}.summary-line{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #eee}.strong{font-weight:bold}.footnote,small{font-size:11px;color:#666}@media print{tr{break-inside:avoid}}</style>'+ $('printArea').innerHTML+'</html>']);files.push(['LEIA-ME.txt','KLSistemas '+VERSION+' — pacote gerencial para conferencia contabil.\nEmpresa: '+cfg().name+'\nCNPJ: '+cfg().cnpj+'\nPeriodo: '+filterMonth+'\nCSV: UTF-8, separador ponto e virgula, decimal virgula.\nVendas e notas possuem uma linha por item: nao some o total do documento repetido em cada linha.\nContas, fiados e inventario refletem a posicao atual, nao um saldo historico no fim do mes.\nTributos, taxas e ajustes dependem dos lancamentos e da validacao do contador.\nNao substitui SPED, livros fiscais ou emissao de NF-e. XMLs originais de entrada estao incluidos quando importados.\n']);for(const n of db().invoices.filter(n=>n.xml&&localDay(n.date).startsWith(filterMonth)))files.push(['xml/'+String(n.id)+'.xml',n.xml]);const blob=zipFiles(files),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='KLSistemas_Contador_'+filterMonth+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Pacote do contador exportado.')}
function loginView(){closeModal();ready=false;document.body.classList.add('login-mode');$('main').innerHTML=`<div class="card cloud-login"><div class="brand" style="color:var(--accent);margin-bottom:24px">KLSistemas</div><h1>Acesse sua empresa</h1><p class="subtitle">Cada empresa tem login e dados separados.</p><form id="cloudLogin" onsubmit="event.preventDefault();loginCloud()"><label>Usuário<input id="cloudUser" autocomplete="username" required></label><label>Senha<input id="cloudPassword" type="password" autocomplete="current-password" required></label><p id="loginError" role="alert"></p><button class="full" type="submit">Entrar</button>${managedPortal?'<p class="subtitle">Solicite acesso ao administrador da plataforma.</p>':'<button class="secondary full" type="button" style="margin-top:10px" onclick="registerView()">Cadastrar uma empresa</button>'}</form></div>`}
async function loginCloud(){const user=$('cloudUser').value,password=$('cloudPassword').value;const b=$('cloudLogin').querySelector('button');b.disabled=true;try{const r=await fetch('/mercado/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:user,password})});const result=await r.json();if(!r.ok)throw Error(result.error||'Falha ao entrar');$('cloudPassword').value='';document.body.classList.remove('login-mode');await boot()}catch(e){if($('loginError'))$('loginError').textContent=e.message}finally{if(b)b.disabled=false}}
function registerView(){document.body.classList.add('login-mode');$('main').innerHTML=`<div class="card cloud-login"><div class="brand" style="color:var(--accent);margin-bottom:24px">KLSistemas</div><h1>Cadastre sua empresa</h1><p class="subtitle">Os dados desta empresa ficarão separados das demais.</p><form id="cloudRegister" onsubmit="event.preventDefault();registerCloud()"><label>Nome da empresa<input id="regCompany" maxlength="120" required autocomplete="organization"></label><label>CNPJ ou CPF (opcional)<input id="regDocument" maxlength="32" autocomplete="off"></label><label>Crie um usuário<input id="regUser" minlength="3" maxlength="120" required autocomplete="username"></label><label>Crie uma senha (mínimo 12 caracteres)<input id="regPassword" type="password" minlength="12" maxlength="1024" required autocomplete="new-password"></label><p class="muted" style="font-size:11px">Guarde seu usuário e sua senha: a recuperação automática ainda não está disponível.</p><p id="loginError" role="alert"></p><button class="full" type="submit">Criar empresa</button><button class="secondary full" type="button" style="margin-top:10px" onclick="loginView()">Voltar ao login</button></form></div>`}
async function registerCloud(){const form=$('cloudRegister'),b=form.querySelector('button[type="submit"]'),password=$('regPassword').value;b.disabled=true;try{const r=await fetch('/mercado/api/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({companyName:$('regCompany').value,document:$('regDocument').value,username:$('regUser').value,password})});const result=await r.json();if(!r.ok)throw Error(result.error||'Falha ao cadastrar empresa');$('regPassword').value='';document.body.classList.remove('login-mode');await boot()}catch(e){if($('loginError'))$('loginError').textContent=e.message}finally{if(b)b.disabled=false}}
async function logoutCloud(){if(cart.length&&!confirm('Sair e descartar o carrinho não finalizado?'))return;await api('/api/logout',{});cart=[];location.reload()}
boot();
